from datetime import date, timedelta
import calendar

def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    tokens = rule.split()
    results = []

    if tokens[0] == "DAILY":
        K = int(tokens[1])
        d = start_date
        while len(results) < count:
            results.append(d.isoformat())
            d += timedelta(days=K)

    elif tokens[0] == "WEEKLY":
        K = int(tokens[1])
        day_codes = tokens[2].split(",")
        code_to_weekday = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}
        target_weekdays = set(code_to_weekday[c] for c in day_codes)

        # Week 0 is the Monday-Sunday week containing start_date
        # Find the Monday of that week
        start_monday = start_date - timedelta(days=start_date.weekday())

        week_num = 0
        while len(results) < count:
            if week_num % K == 0:
                # This week is active
                for wd in range(7):
                    if wd in target_weekdays:
                        candidate = start_monday + timedelta(weeks=week_num, days=wd)
                        if candidate >= start_date:
                            results.append(candidate.isoformat())
                            if len(results) == count:
                                break
            week_num += 1

    elif tokens[0] == "MONTHLY":
        K = int(tokens[1])

        if len(tokens) == 3:
            # MONTHLY K D
            D = int(tokens[2])

            # Month 0 is the month of start
            start_year = start_date.year
            start_month = start_date.month

            month_num = 0
            while len(results) < count:
                # Compute actual year/month for month_num
                total_months = (start_year - 1) * 12 + (start_month - 1) + month_num
                year = total_months // 12 + 1
                month = total_months % 12 + 1

                if month_num % K == 0:
                    days_in_month = calendar.monthrange(year, month)[1]
                    if D == -1:
                        day = days_in_month
                    else:
                        day = D
                    if 1 <= day <= days_in_month:
                        candidate = date(year, month, day)
                        if candidate >= start_date:
                            results.append(candidate.isoformat())
                month_num += 1

        else:
            # MONTHLY K N WD
            N = int(tokens[2])
            WD_code = tokens[3]
            code_to_weekday = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}
            target_wd = code_to_weekday[WD_code]

            start_year = start_date.year
            start_month = start_date.month

            month_num = 0
            while len(results) < count:
                total_months = (start_year - 1) * 12 + (start_month - 1) + month_num
                year = total_months // 12 + 1
                month = total_months % 12 + 1

                if month_num % K == 0:
                    days_in_month = calendar.monthrange(year, month)[1]
                    # Find all days in this month matching target_wd
                    matching_days = []
                    for day in range(1, days_in_month + 1):
                        if date(year, month, day).weekday() == target_wd:
                            matching_days.append(day)
                    if N == -1:
                        if matching_days:
                            day = matching_days[-1]
                            candidate = date(year, month, day)
                            if candidate >= start_date:
                                results.append(candidate.isoformat())
                    else:
                        if N <= len(matching_days):
                            day = matching_days[N - 1]
                            candidate = date(year, month, day)
                            if candidate >= start_date:
                                results.append(candidate.isoformat())
                month_num += 1

    elif tokens[0] == "YEARLY":
        K = int(tokens[1])
        mm_dd = tokens[2]
        mm, dd = int(mm_dd.split("-")[0]), int(mm_dd.split("-")[1])

        start_year = start_date.year
        year_num = 0
        while len(results) < count:
            year = start_year + year_num
            if year_num % K == 0:
                # Check if date exists in this year
                try:
                    candidate = date(year, mm, dd)
                    if candidate >= start_date:
                        results.append(candidate.isoformat())
                except ValueError:
                    pass  # Date doesn't exist (e.g., Feb 29 in non-leap year)
            year_num += 1

    return results
